"use client";

import { motion, useReducedMotion } from "framer-motion";

const PULSE_DELAYS = [0, 0.6, 1.2] as const;

export function PulseLoader({
  icon,
  size = 56,
  label = "Loading",
}: {
  icon?: React.ReactNode;
  size?: number;
  label?: string;
}) {
  const shouldReduceMotion = useReducedMotion();
  const medallionSize = size * 0.42;

  return (
    <div
      role="status"
      aria-label={label}
      className="relative inline-flex items-center justify-center"
      style={{ width: size, height: size }}
    >
      {shouldReduceMotion ? (
        <motion.span
          aria-hidden
          className="absolute rounded-full border border-emerald-400/40 dark:border-emerald-300/30"
          style={{
            width: medallionSize * 1.3,
            height: medallionSize * 1.3,
            top: "50%",
            left: "50%",
            marginLeft: -(medallionSize * 1.3) / 2,
            marginTop: -(medallionSize * 1.3) / 2,
          }}
          animate={{ opacity: [0.25, 0.5, 0.25] }}
          transition={{ duration: 1.6, repeat: Infinity, ease: "easeInOut" }}
        />
      ) : (
        PULSE_DELAYS.map((delay, i) => (
          <motion.span
            key={i}
            aria-hidden
            className="absolute rounded-full border border-emerald-400/50 dark:border-emerald-300/40"
            style={{
              width: medallionSize,
              height: medallionSize,
              top: "50%",
              left: "50%",
              marginLeft: -medallionSize / 2,
              marginTop: -medallionSize / 2,
            }}
            initial={{ opacity: 0.55, scale: 1 }}
            animate={{ opacity: 0, scale: 2.2 }}
            transition={{ duration: 1.8, repeat: Infinity, ease: [0.22, 1, 0.36, 1], delay }}
          />
        ))
      )}

      <div
        className="relative flex items-center justify-center rounded-full bg-white text-emerald-700 shadow-[0_2px_10px_-2px_rgba(5,150,105,0.35)] dark:bg-neutral-950 dark:text-emerald-400"
        style={{ width: medallionSize, height: medallionSize }}
      >
        <motion.span
          aria-hidden
          className="absolute inset-0 rounded-full bg-emerald-400/25 blur-sm dark:bg-emerald-400/20"
          animate={
            shouldReduceMotion ? { opacity: 0.35 } : { opacity: [0.2, 0.45, 0.2], scale: [0.92, 1.04, 0.92] }
          }
          transition={{ duration: 1.8, repeat: Infinity, ease: "easeInOut" }}
        />
        {/* absolute + inset-0 gives this a definite box to center against (a shrink-to-fit
            span here would leave a percentage-sized SVG child mis-measured and left-anchored) */}
        <span className="absolute inset-0 flex items-center justify-center">
          {icon ?? (
            <svg viewBox="0 0 24 24" width="40%" height="40%" fill="currentColor" aria-hidden>
              <circle cx="12" cy="12" r="6" />
            </svg>
          )}
        </span>
      </div>
    </div>
  );
}
